import{_ as t,o as e,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"课程设计与实训","description":"","frontmatter":{},"headers":[],"relativePath":"实验与实践/课程设计与实训.md","filePath":"实验与实践/课程设计与实训.md","lastUpdated":1792430298000}'),o={name:"实验与实践/课程设计与实训.md"};function i(n,a,s,h,d,_){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="课程设计与实训" tabindex="-1">课程设计与实训 <a class="header-anchor" href="#课程设计与实训" aria-label="Permalink to &quot;课程设计与实训&quot;">​</a></h1><blockquote><p>实践性教学环节是 FAFU 网安专业的重点：课程设计、综合实训、毕业设计层层递进，把「学过」变成「会做」。</p></blockquote><h2 id="课程设计-课程内大作业" tabindex="-1">课程设计（课程内大作业） <a class="header-anchor" href="#课程设计-课程内大作业" aria-label="Permalink to &quot;课程设计（课程内大作业）&quot;">​</a></h2><p>培养方案中的主要课程设计环节（以教务安排为准）：</p><ul><li><strong>数据结构（课程设计）</strong>：独立完成一个完整项目（如图书管理系统、校园导航等），重点训练编码与工程规范；</li><li><strong>数据库安全（课程设计）</strong>：带安全设计（权限矩阵、审计、加密字段）的数据库应用；</li><li><strong>操作系统安全（课程设计）</strong>：系统加固或安全机制实验。</li></ul><p><strong>怎么做才值</strong>：不要只求「通过」，把课程设计当成作品来做——写好 README、画好架构图、留好 Git 提交记录，它就是简历上的项目。</p><h2 id="综合实训" tabindex="-1">综合实训 <a class="header-anchor" href="#综合实训" aria-label="Permalink to &quot;综合实训&quot;">​</a></h2><ul><li>校内实训依托<strong>网络安全虚拟仿真实验系统、信息安全实训平台、网络舆情监测系统</strong>等设备（学院投资建设）；</li><li>形式多为「攻防演练 / 靶场通关 / 综合项目」，与 <a href="./../安全方向/网络攻防.html">网络攻防</a> 课程呼应。</li></ul><h2 id="毕业设计" tabindex="-1">毕业设计 <a class="header-anchor" href="#毕业设计" aria-label="Permalink to &quot;毕业设计&quot;">​</a></h2><ul><li>大四完成，选题建议结合主攻方向：漏洞分析、安全工具、检测系统、隐私保护方案、智慧农林安全应用等；</li><li>提前（大三下）确定方向并准备素材，避免大四仓促。</li></ul><h2 id="实训规范提醒" tabindex="-1">实训规范提醒 <a class="header-anchor" href="#实训规范提醒" aria-label="Permalink to &quot;实训规范提醒&quot;">​</a></h2><ul><li>实训均在校内授权平台进行，遵守实验室安全规范；</li><li>涉及真实数据的项目注意脱敏与合规（见 <a href="./../安全方向/法律伦理与合规.html">法律伦理与合规</a>）。</li></ul>',12)])])}const p=t(o,[["render",i]]);export{u as __pageData,p as default};
